import os
import requests

BASE_URL = os.getenv("API_BASE_URL", "https://api.socbench.example").rstrip("/")
API_KEY = os.getenv("API_KEY")

session = requests.Session()
if API_KEY:
    session.headers["Authorization"] = f"Bearer {API_KEY}"

session.headers["Accept"] = "application/json"

region = os.getenv("REGION", "North America")
product_upc = os.getenv("PRODUCT_UPC", "012345678905")
product_id = os.getenv("PRODUCT_ID")
product_name = os.getenv("PRODUCT_NAME", "")
age_group = os.getenv("AGE_GROUP", "18-34")
location = os.getenv("DEMOGRAPHIC_LOCATION", region)

def get(path, **kwargs):
    response = session.get(f"{BASE_URL}{path}", **kwargs)
    response.raise_for_status()
    return response.json()

version = get("/version")

trends = get("/consumer-trends/overview", params={"region": region})
demographic_preferences = get(
    "/demographics/preferences",
    params={"age": age_group, "location": location},
)
product_rating = get(f"/products/{product_upc}/rating")
ingredients = get(f"/products/{product_upc}/ingredients")

# Use the product's UPC to find its product ID if one was not supplied.
if not product_id:
    search_results = get("/products/search", params={"productId": product_upc})
    results = search_results if isinstance(search_results, list) else search_results.get(
        "products", []
    )
    if results:
        product_id = results[0].get("productId")

# Identify high-demand regions from the trend response and retrieve inventory forecasts.
high_demand_regions = []
if isinstance(trends, dict):
    regions = trends.get("regions", [])
    for item in regions:
        if isinstance(item, dict) and (
            item.get("highDemand") is True
            or str(item.get("demandLevel", "")).lower() in {"high", "very high"}
        ):
            name = item.get("region") or item.get("name")
            if name:
                high_demand_regions.append(name)

if not high_demand_regions:
    high_demand_regions = [region]

inventory_forecasts = []
for forecast_region in high_demand_regions:
    inventory_forecasts.append(
        {
            "region": forecast_region,
            "forecast": get(
                "/inventory/demand-forecast",
                params={"region": forecast_region, "productId": product_id or product_upc},
            ),
        }
    )

updated_product = None
if product_id:
    details = {
        "productName": product_name,
        "details": (
            f"Updated using consumer trends for {region}, demographic preferences "
            f"for age group {age_group} in {location}, sustainability rating, "
            f"ingredient information, and inventory demand forecasts."
        ),
    }
    details = {key: value for key, value in details.items() if value}
    response = session.patch(
        f"{BASE_URL}/products/{product_id}",
        json=details,
    )
    response.raise_for_status()
    updated_product = response.json() if response.content else None

results = {
    "api_version": version,
    "consumer_trends": trends,
    "demographic_preferences": demographic_preferences,
    "sustainability_rating": product_rating,
    "ingredients": ingredients,
    "inventory_forecasts": inventory_forecasts,
    "updated_product": updated_product,
}

