import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()

# Retrieve the top-rated sustainable products across categories.
top_response = session.get(f"{BASE_URL}/products/top-rated")
top_response.raise_for_status()
top_data = top_response.json()

# Accept either a direct list or a list nested in a common response field.
if isinstance(top_data, list):
    products = top_data
else:
    products = next(
        (top_data[key] for key in ("products", "results", "data") if isinstance(top_data.get(key), list)),
        [],
    )

# Fetch detailed product information and retailer pricing for each product.
enriched_products = []
for product in products:
    product_id = product.get("productId", product.get("product_id", product.get("id")))
    if product_id is None:
        continue

    detail_response = session.get(f"{BASE_URL}/products/{product_id}")
    detail_response.raise_for_status()
    details = detail_response.json()

    price_response = session.get(f"{BASE_URL}/products/{product_id}/prices")
    price_response.raise_for_status()
    pricing = price_response.json()

    enriched_products.append(
        {
            "id": product_id,
            "top_rated": product,
            "details": details,
            "pricing": pricing,
        }
    )

# Request seasonal predictions for the selected products over the next quarter.
prediction_response = session.post(
    f"{BASE_URL}/seasonal-trends/predictions",
    json={
        "productIds": [item["id"] for item in enriched_products],
        "period": "next_quarter",
    },
)
prediction_response.raise_for_status()
predictions = prediction_response.json()

# Compare retailer prices and submit update requests for observed discrepancies.
price_update_requests = []
for item in enriched_products:
    pricing = item["pricing"]
    if isinstance(pricing, dict):
        retailer_prices = pricing.get("prices", pricing.get("retailers", []))
    else:
        retailer_prices = pricing

    if not isinstance(retailer_prices, list) or len(retailer_prices) < 2:
        continue

    observed_prices = []
    for entry in retailer_prices:
        if not isinstance(entry, dict):
            continue
        price = entry.get("price")
        if price is not None:
            observed_prices.append(
                {
                    "retailerId": entry.get("retailerId", entry.get("retailer_id")),
                    "location": entry.get("location"),
                    "price": price,
                }
            )

    if len(observed_prices) < 2:
        continue

    numeric_prices = [entry["price"] for entry in observed_prices if isinstance(entry["price"], (int, float))]
    if len(numeric_prices) < 2 or min(numeric_prices) == max(numeric_prices):
        continue

    suggested_price = sum(numeric_prices) / len(numeric_prices)
    update_response = session.post(
        f"{BASE_URL}/request_update",
        json={
            "productId": item["id"],
            "observedPrices": observed_prices,
            "suggestedPrice": suggested_price,
            "reason": "Discrepancy observed across retailer pricing",
        },
    )
    update_response.raise_for_status()
    price_update_requests.append(update_response.json())

result = {
    "products": enriched_products,
    "seasonal_predictions": predictions,
    "price_update_requests": price_update_requests,
}

