import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()

categories_response = session.get(f"{BASE_URL}/product-categories/top")
categories_response.raise_for_status()
top_categories = categories_response.json()

inventory_response = session.get(f"{BASE_URL}/inventory-levels")
inventory_response.raise_for_status()
inventory_levels = inventory_response.json()

retailers_response = session.get(f"{BASE_URL}/retailers")
retailers_response.raise_for_status()
retailers = retailers_response.json()

locations_response = session.get(f"{BASE_URL}/locations")
locations_response.raise_for_status()
locations = locations_response.json()

# Match inventory records to the in-demand categories and identify retailers
# represented in those records.
category_ids = {
    category.get("id", category.get("categoryId"))
    for category in top_categories
    if isinstance(category, dict)
}
category_names = {
    category.get("name", category.get("categoryName"))
    for category in top_categories
    if isinstance(category, dict)
}

relevant_inventory = []
retailer_ids = set()

for item in inventory_levels:
    if not isinstance(item, dict):
        continue

    category_id = item.get("categoryId")
    category_name = item.get("categoryName", item.get("category"))
    if category_id in category_ids or category_name in category_names:
        relevant_inventory.append(item)
        retailer_id = item.get("retailerId")
        if retailer_id is not None:
            retailer_ids.add(retailer_id)

retailers_by_id = {
    retailer.get("id", retailer.get("retailerId")): retailer
    for retailer in retailers
    if isinstance(retailer, dict)
}
identified_retailers = [
    retailers_by_id[retailer_id]
    for retailer_id in retailer_ids
    if retailer_id in retailers_by_id
]

# Retrieve each identified retailer's products and associate available locations.
retailer_details = []
for retailer in identified_retailers:
    retailer_id = retailer.get("id", retailer.get("retailerId"))
    products_response = session.get(
        f"{BASE_URL}/retailers/{retailer_id}/products"
    )
    products_response.raise_for_status()

    retailer_details.append({
        "retailer": retailer,
        "products": products_response.json(),
        "locations": [
            location for location in locations
            if isinstance(location, dict)
            and location.get("retailerId") == retailer_id
        ],
    })

# Report category or availability gaps found in the inventory snapshot.
inventory_category_ids = {
    item.get("categoryId")
    for item in inventory_levels
    if isinstance(item, dict) and item.get("categoryId") is not None
}
inventory_category_names = {
    item.get("categoryName", item.get("category"))
    for item in inventory_levels
    if isinstance(item, dict)
}
gaps = []

for category in top_categories:
    if not isinstance(category, dict):
        continue
    category_id = category.get("id", category.get("categoryId"))
    category_name = category.get("name", category.get("categoryName"))
    if category_id not in inventory_category_ids and category_name not in inventory_category_names:
        gaps.append({
            "categoryId": category_id,
            "categoryName": category_name,
            "issue": "No matching inventory records found for an in-demand category.",
        })

for item in relevant_inventory:
    quantity = item.get("quantity", item.get("stockLevel", item.get("availableQuantity")))
    if quantity is not None and quantity <= 0:
        gaps.append({
            "productId": item.get("productId"),
            "categoryId": item.get("categoryId"),
            "categoryName": item.get("categoryName", item.get("category")),
            "locationId": item.get("locationId"),
            "issue": "Product availability is zero or below at this location.",
        })

feedback = {
    "topCategories": top_categories,
    "inventoryLevels": relevant_inventory,
    "retailers": retailer_details,
    "gapsOrDiscrepancies": gaps,
}

# The documented API provides no feedback-submission endpoint; retain the
# analysis locally rather than sending it to an undocumented route.
print(feedback)

